/**
 * Append-only event ledger. Balances are derived by folding the event stream.
 */
const ledgerStates = new WeakMap()

function validateEvent(event) {
  if (event === null || typeof event !== 'object') throw new TypeError('event must be an object')
  if (event.type !== 'debit' && event.type !== 'credit') throw new Error('event type must be debit or credit')
  if (!Number.isSafeInteger(event.amountCents) || event.amountCents <= 0) {
    throw new Error('amount must be a positive safe integer')
  }
}

function applyEvent(balances, event) {
  const current = balances.get(event.account) ?? 0
  const next = current + (event.type === 'credit' ? event.amountCents : -event.amountCents)
  if (!Number.isSafeInteger(next)) throw new Error('balance exceeds safe integer range')
  if (next < 0) throw new Error('insufficient funds')
  balances.set(event.account, next)
}

function commit(state, pending) {
  const nextBalances = new Map(state.balances)
  for (const event of pending) {
    validateEvent(event)
    applyEvent(nextBalances, event)
  }

  const start = state.events.length
  const committed = pending.map((event, index) => ({ seq: start + index, ...event }))
  state.events.push(...committed)
  state.balances = nextBalances
}

export function createLedger() {
  const state = { events: [], balances: new Map() }
  const ledger = {
    append(event) {
      commit(state, [{ ...event }])
    },
    eventCount() {
      return state.events.length
    },
    fold() {
      const balances = new Map()
      for (const event of state.events) {
        const current = balances.get(event.account) ?? 0
        balances.set(event.account, current + (event.type === 'credit' ? event.amountCents : -event.amountCents))
      }
      return Object.fromEntries(balances)
    },
    events() {
      return state.events.map((event) => ({ ...event }))
    },
  }
  ledgerStates.set(ledger, state)
  return ledger
}

/**
 * Commit related events as one synchronous operation. This is intentionally not
 * re-exported from index.js; it is an implementation detail used by transfer.
 */
export function appendAtomically(ledger, events) {
  const state = ledgerStates.get(ledger)
  if (state === undefined) {
    // Preserve compatibility with ledger-like objects accepted by transfer.
    for (const event of events) ledger.append(event)
    return
  }
  commit(state, events.map((event) => ({ ...event })))
}

/**
 * Append-only event ledger. Balances are derived by folding the event stream.
 */
const ledgerStates = new WeakMap()

function validateEvent(event) {
  if (event === null || typeof event !== 'object') throw new TypeError('event must be an object')
  if (event.type !== 'debit' && event.type !== 'credit') throw new Error('event type must be debit or credit')
  if (!Number.isSafeInteger(event.amountCents) || event.amountCents <= 0) {
    throw new Error('amount must be a positive safe integer')
  }
}

function applyEvent(balances, event) {
  const current = balances.get(event.account) ?? 0
  const next = current + (event.type === 'credit' ? event.amountCents : -event.amountCents)
  if (!Number.isSafeInteger(next)) throw new Error('balance exceeds safe integer range')
  if (next < 0) throw new Error('insufficient funds')
  balances.set(event.account, next)
}

function commit(state, pending) {
  const nextBalances = new Map(state.balances)
  for (const event of pending) {
    validateEvent(event)
    applyEvent(nextBalances, event)
  }

  const start = state.events.length
  const committed = pending.map((event, index) => ({ seq: start + index, ...event }))
  state.events.push(...committed)
  state.balances = nextBalances
}

export function createLedger() {
  const state = { events: [], balances: new Map() }
  const ledger = {
    append(event) {
      commit(state, [{ ...event }])
    },
    eventCount() {
      return state.events.length
    },
    fold() {
      const balances = new Map()
      for (const event of state.events) {
        const current = balances.get(event.account) ?? 0
        balances.set(event.account, current + (event.type === 'credit' ? event.amountCents : -event.amountCents))
      }
      return Object.fromEntries(balances)
    },
    events() {
      return state.events.map((event) => ({ ...event }))
    },
  }
  ledgerStates.set(ledger, state)
  return ledger
}

/** Internal atomic append used by transfer; not part of the public index API. */
export function appendAtomically(ledger, events) {
  const state = ledgerStates.get(ledger)
  if (state === undefined) {
    // Preserve support for ledger-like objects accepted by the existing API.
    for (const event of events) ledger.append(event)
    return
  }
  commit(state, events.map((event) => ({ ...event })))
}

/**
 * Balance snapshot cache. Each ledger has an isolated cache. Reads always catch
 * up with events since the last full fold, while a full fold is performed every
 * REFRESH_EVERY events to keep the snapshot bounded and self-correcting.
 */
const REFRESH_EVERY = 8

let caches = new WeakMap()

function freshCache(ledger, count) {
  return { atCount: count, foldedAt: count, balances: ledger.fold() }
}

export function getBalance(ledger, account) {
  const count = ledger.eventCount()
  let cache = caches.get(ledger)

  // A decreasing count means a nonstandard ledger was reset or replaced.
  if (cache === undefined || count < cache.atCount || count >= cache.foldedAt + REFRESH_EVERY) {
    cache = freshCache(ledger, count)
  } else if (count > cache.atCount) {
    const events = ledger.events()
    // If a ledger cannot provide the expected suffix, fold rather than return a
    // value that may not describe its current stream.
    if (events.length < count) {
      cache = freshCache(ledger, count)
    } else {
      const balances = { ...cache.balances }
      for (let index = cache.atCount; index < count; index += 1) {
        const event = events[index]
        const current = balances[event.account] ?? 0
        balances[event.account] = current + (event.type === 'credit' ? event.amountCents : -event.amountCents)
      }
      cache = { ...cache, atCount: count, balances }
    }
  }

  caches.set(ledger, cache)
  return cache.balances[account] ?? 0
}

export function resetSnapshotCache() {
  caches = new WeakMap()
}

import { appendAtomically } from './ledger.js'
import { getBalance } from './snapshot.js'

/**
 * Transfer money between two accounts. Validates the sender's balance, appends
 * a DEBIT then a CREDIT atomically, and finally notifies hooks.onSettled. The
 * settled notification runs after the ledger has been updated.
 */
export function transfer(ledger, from, to, amountCents, hooks = {}) {
  if (!Number.isSafeInteger(amountCents) || amountCents <= 0) {
    throw new Error('amount must be positive')
  }

  // Resolve caller code before the final balance check. A clock/id callback may
  // throw or even originate another transfer; neither can leave a half-transfer
  // behind or invalidate the overdraft check below.
  const ts = hooks.clock?.() ?? Date.now()
  const start = ledger.eventCount()
  const debitId = hooks.nextId?.() ?? `evt-${start}`
  const creditId = hooks.nextId?.() ?? `evt-${start + 1}`

  if (getBalance(ledger, from) < amountCents) throw new Error('insufficient funds')

  appendAtomically(ledger, [
    { type: 'debit', account: from, amountCents, ts, id: debitId },
    { type: 'credit', account: to, amountCents, ts, id: creditId },
  ])
  hooks.onSettled?.({ from, to, amountCents, ts })
  return true
}

